package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.net.Uri;
import android.graphics.Bitmap;
import android.widget.*;
/** Shared upload/crop sheet. Cancel never writes an image or updates the profile. */
final class ProfileImageUploadDialog {
 static void show(MainActivity activity,Uri uri,String field){show(activity,uri,field,"");}
 static void existingAvatar(Context c,String source){if(c instanceof MainActivity)show((MainActivity)c,null,"avatar_url",source);}
 private static void show(MainActivity activity,Uri uri,String field,String source){
  boolean avatar=field.equals("avatar_url"),background=field.equals("fundo")||field.equals("retro_cover");NativeSheet sheet=new NativeSheet(activity,background?"Atualizar imagem":avatar?"Enquadrar foto":"Enquadrar capa");ProfileCoverView preview=new ProfileCoverView(activity,"");
  LinearLayout.LayoutParams layout=new LinearLayout.LayoutParams(avatar?NativeSheet.dp(activity,210):-1,NativeSheet.dp(activity,avatar?210:180));layout.gravity=android.view.Gravity.CENTER_HORIZONTAL;preview.setBackground(AppStyle.shape(preview,0xff111722,avatar?105:16));preview.setClipToOutline(true);sheet.body.addView(preview,layout);
  LinearLayout controls=background?new LinearLayout(activity):ProfileImageControls.add(activity,sheet.body,preview);if(background)preview.setEnabled(false);
  TextView status=NativeSheet.status(activity,"",12,0xffaaa3b8);sheet.body.addView(status);ProgressBar progress=new ProgressBar(activity,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);progress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(NativeTheme.accent(activity)));progress.setContentDescription("Envio da imagem em andamento");progress.setVisibility(android.view.View.GONE);sheet.body.addView(progress,new LinearLayout.LayoutParams(-1,NativeSheet.dp(activity,4)));sheet.footer.setVisibility(android.view.View.VISIBLE);Button save=new Button(activity);save.setText("Salvar imagem");AppStyle.button(save,true);sheet.footer.addView(save);final Bitmap[] owned={null};sheet.dialog.setOnDismissListener(d->{if(owned[0]!=null){owned[0].recycle();owned[0]=null;}});
  if(uri!=null){save.setEnabled(false);java.util.concurrent.ExecutorService decoder=java.util.concurrent.Executors.newSingleThreadExecutor();decoder.execute(()->{try{Bitmap bitmap=ProfileImages.decode(activity.getApplicationContext(),uri);activity.runOnUiThread(()->{if(sheet.dialog.isShowing()){owned[0]=bitmap;preview.setImageBitmap(bitmap);save.setEnabled(true);}else bitmap.recycle();});}catch(Exception e){activity.runOnUiThread(()->status.setText("Não foi possível abrir a imagem. Escolha JPG, PNG ou WebP de até 10 MB."));}finally{decoder.shutdown();}});}else AccountImageLoader.load(preview,source);
  save.setOnClickListener(v->{if(!preview.ready()){status.setText("Aguarde a imagem carregar. Se não aparecer, escolha outra imagem.");return;}sheet.busy(true);save.setEnabled(false);preview.setEnabled(false);ProfileImageControls.enabled(controls,false);status.setText("Salvando imagem…");progress.setVisibility(android.view.View.VISIBLE);AccountRepository.Callback done=(rows,error)->{sheet.busy(false);progress.setVisibility(android.view.View.GONE);if(!sheet.dialog.isShowing())return;if(error!=null){status.setText(error);save.setEnabled(true);preview.setEnabled(!background);ProfileImageControls.enabled(controls,true);return;}AccountImageLoader.clear();sheet.dialog.dismiss();Toast.makeText(activity,"Imagem salva",Toast.LENGTH_SHORT).show();activity.openProfile();};AccountRepository repo=new AccountRepository(activity);if(uri!=null)repo.uploadProfile(uri,field,preview.crop.x,preview.crop.y,preview.crop.zoom,done);else repo.uploadAvatar(((android.graphics.drawable.BitmapDrawable)preview.getDrawable()).getBitmap(),preview.crop.x,preview.crop.y,preview.crop.zoom,done);});sheet.show();
 }
}
